args <- commandArgs(TRUE); root <- args[1]; work <- args[2]
dir.create(work,recursive=TRUE,showWarnings=FALSE)
file.copy(file.path(root,'subworkflows/ENRICHMENT/local/14.Comparison_report.Rmd'),work,overwrite=TRUE)
dir.create(file.path(work,'src'),showWarnings=FALSE)
file.copy(file.path(root,'subworkflows/ENRICHMENT/local/src',c('evidence_flags.R','fcs_selection.R','report_presentation.R','ami_evidence.R')),file.path(work,'src'),overwrite=TRUE)
file.copy(file.path(root,'subworkflows/SCORING/local/src/scoring_io.R'),file.path(work,'src'),overwrite=TRUE)
writeLines(c('Gene\tPosition\tside\tCAAS_score\tp.emp\tp.adj_bh\tcaas_nominal\tcaas_adjusted\tbiochem_groupings','G1.1.Homo_sapiens\t0\ttop\t0.9\t0.01\t0.02\tTRUE\tTRUE\tGS1','G1.1.Homo_sapiens\t1\ttop\t0.4\t0.2\t0.3\tFALSE\tFALSE\tGS2','G2\t1\tbottom\t0.7\t0.01\t0.02\tTRUE\tTRUE\t'),file.path(work,'scores.tsv'))
writeLines(c('Gene\tPosition\thg38_nt_coord','G1.1.Homo_sapiens\t0\tchr1:1000000','G1.1.Homo_sapiens\t1\tchr1:1000001','G2\t1\tNA'),file.path(work,'char.tsv'))
writeLines(c('gene,position,max_bf,target_aa','G1.1,0,100,S'),file.path(work,'fade.csv'))
writeLines(c('Gene\tcaas_p.gen\tcaas_p.gen.adj\tcaas_p.gen_top\tcaas_p.gen.adj_top\tcaas_p.gen_bottom\tcaas_p.gen.adj_bottom\trer_min_pval\trer_perm_padj\tfade_max_bf_top\tfade_significant_top\tfade_max_bf_bottom\tfade_significant_bottom','G1\t0.01\t0.02\t0.01\t0.02\t0.3\t0.4\t0.02\t0.03\t100\tTRUE\t1\tFALSE','G2\t0.5\t0.6\t0.5\t0.6\t0.01\t0.02\t0.3\t0.4\t1\tFALSE\t1\tFALSE','G3\t0.02\t0.03\t0.02\t0.03\t0.2\t0.3\tNA\tNA\tNA\tNA\tNA\tNA'),file.path(work,'genes.tsv'))
writeLines('{"gene_stat":"max","nominal_threshold":0.05,"fdr_threshold":0.05}',file.path(work,'metadata.json'))
e <- new.env(); rmarkdown::render(file.path(work,'14.Comparison_report.Rmd'),output_dir=work,quiet=TRUE,envir=e,params=list(traitname='validate',fcs_dir=file.path(work,'no'),fcs_le_dir=file.path(work,'no'),position_scores_file=file.path(work,'scores.tsv'),position_characterization_file=file.path(work,'char.tsv'),fade_sites_top_file=file.path(work,'fade.csv'),gene_scores_file=file.path(work,'genes.tsv'),gene_metadata_file=file.path(work,'metadata.json')))
stopifnot(isTRUE(e$positive_characterization$fade_selected[e$positive_characterization$Position==0]), nrow(e$positive_characterization)==3, is.na(e$positive_characterization$fade_selected[e$positive_characterization$side=='bottom']))
w<-e$regional_characterization;stopifnot(nrow(w)==2,all(sort(w$window_start)==c(1,1000001)),sum(w$n_positions)==2,w$n_top_decile[w$window_start==1]==1,w$n_top_decile[w$window_start==1000001]==0)
g<-e$gene_overlap_cmp; a<-g[g$ranking=='global' & g$tool=='RER' & g$call=='nominal',]; stopifnot(a$shared_tested_universe==2,a$both==1,a$neither==1)
h<-paste(readLines(file.path(work,'14.Comparison_report.html'),warn=FALSE),collapse=' ');h<-gsub('[[:space:]]+',' ',h);stopifnot(any(grepl('Characterization of positive positions',h)),any(grepl('Gene-level overlap between methods',h)))
cat('COMPARISON_VALIDATION_PASS\n')
